import type { SeniorCourse, SeniorQuestion } from "./year12-question-bank";

type Difficulty = SeniorQuestion["difficulty"];
type QuestionKind = SeniorQuestion["kind"];

export type Year13Topic = {
  id: string;
  year: 13;
  name: string;
  course: SeniorCourse;
  standard: string;
  strand: "Biology" | "Chemistry" | "Physics" | "Agriculture";
  keywords: string[];
  questions: SeniorQuestion[];
  oneWordQuestions: SeniorQuestion[];
};

type QuestionRow = readonly [string, string, Difficulty, QuestionKind];
type OneWordRow = readonly [string, string, Difficulty];

function makeTopic(
  details: Omit<Year13Topic, "year" | "questions" | "oneWordQuestions">,
  rows: QuestionRow[],
  oneWordRows: OneWordRow[],
): Year13Topic {
  return {
    ...details,
    year: 13,
    questions: rows.map(([q, a, difficulty, kind]) => ({ q, a, difficulty, kind })),
    oneWordQuestions: oneWordRows.map(([q, a, difficulty]) => ({ q, a, difficulty, kind: "short" })),
  };
}

