for (const topic of year13Topics) {
  if (topic.questions.length !== 40) {
    throw new Error(`${topic.id} must contain exactly 40 questions; found ${topic.questions.length}.`);
  }

  if (topic.oneWordQuestions.length !== 40) {
    throw new Error(`${topic.id} must contain exactly 40 one-word questions; found ${topic.oneWordQuestions.length}.`);
  }

  for (const bank of [topic.questions, topic.oneWordQuestions]) {
    const unique = new Set(bank.map((question) => question.q.trim().toLowerCase()));
    if (unique.size !== bank.length) {
      throw new Error(`${topic.id} contains duplicate question wording.`);
    }
  }

  for (const difficulty of ["foundation", "core", "stretch"] as const) {
    const expected = difficulty === "core" ? 16 : 12;
    const count = topic.oneWordQuestions.filter((question) => question.difficulty === difficulty).length;
    if (count !== expected) {
      throw new Error(`${topic.id} must contain ${expected} ${difficulty} one-word questions; found ${count}.`);
    }
  }
}
